from pathlib import Path
p=Path('index.html')
s=p.read_text(encoding='utf-8')
a=s.index(' if(raw==="division_remainder"){')
b=s.index(' if(raw==="properties"){',a)
s=s[:a]+" if(raw===\"division_remainder\"){\n  const live=stageOverride===null&&blockSession?.kind===\"g3quiz\"&&blockSession.key===\"g3:division_remainder\";\n  return g3RemainderQuestion(d,live?blockSession.done:null);\n }\n"+s[b:]
anchor='function g3UnitNumberQuestion('
assert s.count(anchor)==1
s=s.replace(anchor,"const G3_REMAINDER_VARIANTS=[\n [\"numeric\",\"check\"],\n [\"apples\",\"pencils\",\"books\"],\n [\"giveAway\",\"receive\",\"join\"]\n];\nfunction g3RemainderQuestion(stage,slot=null){\n const d=Math.max(0,Math.min(2,Number(stage)||0)),variants=G3_REMAINDER_VARIANTS[d];\n const v=slot===null?g6RandomFrom(variants):variants[((slot%variants.length)+variants.length)%variants.length];\n const divisor=ri(2,9),quotient=ri(d===0?2:3,d===0?9:d===1?15:25),\n  remainder=ri(1,divisor-1),dividend=divisor*quotient+remainder;\n const sig=(extra=\"\")=>\"g3:division_remainder:\"+d+\":\"+v+\":\"+dividend+\":\"+divisor+\":\"+extra;\n const base=divisor+\" · \"+quotient+\" = \"+(divisor*quotient)+\".<br>\"+\n   dividend+\" − \"+(divisor*quotient)+\" = \"+remainder+\".<br>\"+\n   \"Проверка: \"+dividend+\" = \"+divisor+\" · \"+quotient+\" + \"+remainder+\n   \", причём \"+remainder+\" < \"+divisor+\".\";\n const remainderQuestion=(text,ex,extra=\"\",data={})=>{\n  const q=g3RemainderInputQuestion(dividend,divisor,quotient,remainder,ex,sig(extra),\n   {stage:d,variant:v,...data});\n  if(text)q.text=text;\n  return q;\n };\n if(v===\"numeric\")return remainderQuestion(null,base);\n if(v===\"check\"){\n  const right=ri(0,1)===0,wrongPlace=ri(0,1),shownQ=right||wrongPlace===1?quotient:quotient+1,\n   shownR=right||wrongPlace===0?remainder:remainder+1;\n  return g6ChoiceQuestion(\"Верно ли деление <b>\"+dividend+\" : \"+divisor+\n   \" = \"+shownQ+\" (ост. \"+shownR+\")</b>?\",\n   right?\"Верно\":\"Неверно\",[\"Верно\",\"Неверно\"],base,sig(shownQ+\":\"+shownR),\n   {type:\"g3Remainder\",stage:d,variant:v,dividend,divisor,quotient,remainder,shownQ,shownR,right});\n }\n if(d===1){\n  const text=v===\"apples\"?\n   g3Qty(dividend,\"apple\")+\" раскладывают по \"+g3Qty(divisor,\"apple\")+\" в пакет. Сколько полных пакетов получится и сколько яблок останется?\":\n   v===\"pencils\"?\n   g3Qty(dividend,\"pencil\")+\" раскладывают по \"+g3Qty(divisor,\"pencil\")+\" в коробку. Сколько полных коробок получится и сколько карандашей останется?\":\n   \"Есть \"+g3Qty(dividend,\"book\")+\". Их раскладывают в стопки по \"+g3Qty(divisor,\"book\")+\". Сколько полных стопок получится и сколько книг останется?\";\n  return remainderQuestion(text,base);\n }\n if(v===\"giveAway\"){\n  const taken=ri(3,12),total=dividend+taken;\n  return remainderQuestion(\"Было \"+g3Qty(total,\"pencil\")+\". \"+g3Qty(taken,\"pencil\")+\n   \" отдали. Остальные раскладывают по \"+g3Qty(divisor,\"pencil\")+\n   \" в коробку. Сколько полных коробок получится и сколько карандашей останется?\",\n   \"После выдачи осталось \"+total+\" − \"+taken+\" = \"+dividend+\".<br>\"+base,\n   total+\":\"+taken,{total,taken});\n }\n if(v===\"receive\"){\n  const added=ri(3,Math.min(15,dividend-1)),start=dividend-added;\n  return remainderQuestion(\"Было \"+g3Qty(start,\"pencil\")+\". Принесли ещё \"+g3Qty(added,\"pencil\")+\n   \". Все карандаши раскладывают по \"+g3Qty(divisor,\"pencil\")+\n   \" в коробку. Сколько полных коробок получится и сколько карандашей останется?\",\n   \"Всего стало \"+start+\" + \"+added+\" = \"+dividend+\".<br>\"+base,\n   start+\":\"+added,{start,added});\n }\n const first=ri(2,dividend-2),second=dividend-first;\n return remainderQuestion(\"В первой партии \"+g3Qty(first,\"book\")+\", во второй — \"+g3Qty(second,\"book\")+\n  \". Все книги раскладывают в стопки по \"+g3Qty(divisor,\"book\")+\n  \". Сколько полных стопок получится и сколько книг останется?\",\n  \"Сначала сложим партии: \"+first+\" + \"+second+\" = \"+dividend+\".<br>\"+base,\n  first+\":\"+second,{first,second});\n}\n\n"+anchor)
assert s.count('function g3RemainderQuestion(')==1
p.write_text(s,encoding='utf-8')
print('patched remainder length',len(s))
